                                        break;
                                    }
                                }
                                else
                                {
                                    path_len--;
                                }
                            }
                        }
                        rt_free(fp);
                    }
                }
            }
            else
            {
                path_len += len;
            }
        }

        return path;

_ERR_RET:
        rt_free(path);
        path = RT_NULL;
    }

    return path;
}

